mapper.select:
SELECT r.id, r.dish_id AS dishId, d.name AS dishName, d.image AS dishImage, s.id AS stallId, s.name AS stallName, r.user_id AS userId, CASE WHEN r.anonymous = 1 THEN '匿名用户' ELSE IFNULL(u.real_name, '已注销用户') END AS userName, CASE WHEN r.anonymous = 1 THEN '' ELSE IFNULL(u.avatar, '') END AS avatar, r.rating, r.content, r.anonymous, r.status, r.merchant_reply AS merchantReply, r.merchant_reply_time AS merchantReplyTime, r.handled, r.like_count AS likeCount, r.view_count AS viewCount, r.reply_count AS replyCount,
(r.user_id = #{currentUserId}) AS mine, EXISTS(SELECT 1 FROM review_like rl WHERE rl.review_id = r.id AND rl.user_id = #{currentUserId}) AS liked
0 AS mine, 0 AS liked
, r.create_time AS createTime FROM dish_review r INNER JOIN dish d ON r.dish_id = d.id AND d.deleted = 0 LEFT JOIN canteen_stall s ON d.stall_id = s.id AND s.deleted = 0 LEFT JOIN sys_user u ON r.user_id = u.id AND u.deleted = 0 WHERE r.deleted = 0
AND r.dish_id = #{query.dishId}
AND r.user_id = #{query.userId}
AND d.stall_id = #{query.stallId}
AND r.rating = #{query.rating}
AND r.status = #{query.status}
AND (r.content LIKE CONCAT('%', #{query.keyword}, '%') OR d.name LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY r.like_count DESC, r.create_time DESC
ORDER BY r.view_count DESC, r.create_time DESC
ORDER BY r.rating DESC, r.create_time DESC
ORDER BY r.rating ASC, r.create_time DESC
ORDER BY r.create_time DESC

SELECT r.id, r.dish_id AS dishId, d.name AS dishName, d.image AS dishImage, d.stall_id AS stallId, s.name AS stallName, r.user_id AS userId, CASE WHEN r.anonymous = 1 THEN '匿名学生' ELSE IFNULL(u.real_name, '已注销学生') END AS userName, CASE WHEN r.anonymous = 1 THEN '' ELSE IFNULL(u.avatar, '') END AS avatar, r.rating, r.content, r.anonymous, r.status, r.merchant_reply AS merchantReply, r.merchant_reply_time AS merchantReplyTime, r.handled, r.like_count AS likeCount, r.view_count AS viewCount, r.reply_count AS replyCount, r.create_time AS createTime FROM dish_review r INNER JOIN dish d ON r.dish_id = d.id AND d.deleted = 0 LEFT JOIN canteen_stall s ON d.stall_id = s.id AND s.deleted = 0 LEFT JOIN sys_user u ON r.user_id = u.id AND u.deleted = 0 WHERE r.deleted = 0 AND d.stall_id = #{stallId}
AND r.rating = #{query.rating}
AND r.handled = #{query.handled}
ORDER BY r.rating DESC, r.create_time DESC
ORDER BY r.rating ASC, r.create_time DESC
ORDER BY r.like_count DESC, r.create_time DESC
ORDER BY r.view_count DESC, r.create_time DESC
ORDER BY r.create_time DESC
